        region = REGION_LOW;

        if (s[2] == 1'b1) begin
            // Above highest sensor
            region = REGION_HIGH;
        end else if (s[1] == 1'b1) begin
            // Between s[1] and s[0]
            // (Assuming valid sensor behavior; otherwise still choose based on asserted sensors)
            region = REGION_MID1;
        end else if (s[1] == 1'b0 && s[2] == 1'b0 && s[0] == 1'b1) begin
            // This would be an odd/invalid pattern in a physical monotonic sensor model,
            // but we map it to the lowest non-low region for determinism.
            region = REGION_LOW;
        end else begin
            // Below s[0]
            region = REGION_LOW;
        end

        // Special case: between s[2] and s[1] means s[2]=1 and s[1]=0.
        // The above if already handles s[2]==1 as REGION_HIGH, so we must refine.
        // Correct refinement order:
        //   - If s[2]==1 and s[1]==0 => mid2
        //   - If s[2]==1 and s[1]==1 => high
        if (s[2] == 1'b1 && s[1] == 1'b0) begin
            region = REGION_MID2;
